from itertools import islice


def iter_batches(source, size):
    """Yield fresh lists of up to size items; source is consumed lazily, never read ahead."""
    iterator = iter(source)
    while True:
        batch = list(islice(iterator, size))
        if not batch:
            return
        yield batch

