def parse_port(raw):
    text = raw.strip()
    # Digits only: int() would also accept "+80" and "8_0", which must not pass.
    if not (text.isascii() and text.isdigit()):
        raise ValueError(f"invalid port: {raw!r}")
    port = int(text)
    if not 0 < port < 65536:
        raise ValueError(f"port out of range: {raw!r}")
    return port

